{
  "name": "@dracondev/opencode-auto-continue",
  "version": "7.8.1839",
  "description": "Auto-continue stalled OpenCode sessions — stall recovery, todo nudging, review on completion, and AI-driven session analysis",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "stall-recovery",
    "session-recovery",
    "auto-recovery",
    "stuck-session",
    "abort",
    "continue"
  ],
  "license": "MIT",
  "author": "dracon",
  "homepage": "https://github.com/DraconDev/opencode-auto-continue",
  "repository": {
    "type": "git",
    "url": "https://github.com/DraconDev/opencode-auto-continue"
  },
  "bugs": {
    "url": "https://github.com/DraconDev/opencode-auto-continue/issues"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.4.10",
    "@types/node": "^20.11.0",
    "typescript": "^5.4.0",
    "vitest": "^2.1.9"
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit",
    "lint": "tsc --noEmit",
    "sync": "npm run build && node -e \"const p=require('./package.json');const fs=require('fs');const path=require('path');fs.writeFileSync('./dist/package.json',JSON.stringify({name:p.name,version:p.version,main:'./index.js',types:'./index.d.ts',description:p.description,peerDependencies:p.peerDependencies},null,2)+'\\n');console.log('sync: dist/package.json v'+p.version);const plugDir=path.join(process.env.HOME||'/tmp','.config','opencode','plugins','opencode-auto-continue');let needLink=true;try{const stat=fs.lstatSync(plugDir);if(stat.isSymbolicLink()){const target=fs.readlinkSync(plugDir);if(target===path.resolve('./dist')){console.log('symlink already correct:',plugDir,'->',target);needLink=false;}else{console.log('replacing stale symlink:',plugDir,'(was',target,')');fs.unlinkSync(plugDir);}}else{console.log('removing existing plugin dir:',plugDir);fs.rmSync(plugDir,{recursive:true});}}catch(e){if(e.code!=='ENOENT')console.log('check symlink:',e.message);}if(needLink){fs.symlinkSync(path.resolve('./dist'),plugDir,'dir');console.log('created symlink:',plugDir,'->',path.resolve('./dist'));}\"",
    "prepublishOnly": "npm run build"
  }
}
